/* PRO portable browser backups. Only this app's explicitly allowed keys are read. */
(()=>{'use strict';
const tag=document.currentScript,app=tag.dataset.proApp,keys=JSON.parse(tag.dataset.proKeys||'[]');
if(!app||!keys.length)return;
const allowed=k=>keys.some(prefix=>k===prefix||prefix.endsWith(':')&&k.startsWith(prefix));
const safe=(v,depth=0)=>{if(depth>30)throw Error('Datos demasiado anidados.');if(v===null||typeof v==='boolean'||typeof v==='number'&&Number.isFinite(v))return;if(typeof v==='string'&&v.length<=100000)return;if(Array.isArray(v)&&v.length<=20000){v.forEach(x=>safe(x,depth+1));return;}if(v&&typeof v==='object'&&Object.keys(v).length<=20000){for(const [k,x]of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Clave no válida.');safe(x,depth+1);}return;}throw Error('Datos no válidos.');};
function merge(current,incoming){if(Array.isArray(current)&&Array.isArray(incoming)){const map=new Map();for(const v of [...incoming,...current]){const key=v&&typeof v==='object'&&v.id?'id:'+v.id:JSON.stringify(v);map.set(key,v&&typeof v==='object'&&map.has(key)?merge(v,map.get(key)):v);}return [...map.values()];}if(current&&incoming&&typeof current==='object'&&typeof incoming==='object'&&!Array.isArray(current)&&!Array.isArray(incoming)){const out={...incoming};for(const [k,v] of Object.entries(current))out[k]=k in incoming?merge(v,incoming[k]):v;return out;}return current===undefined?incoming:current;}
const panel=document.createElement('details');panel.className='pro-transfer';panel.innerHTML='<summary>Copias y traslado de mis datos</summary><h2>Mi copia de seguridad</h2><p>Exporta los perfiles y el progreso de esta aplicación e importa la copia en su otra publicación o en otro dispositivo. Los PDF, imágenes y grabaciones se trasladan por separado. No hay sincronización automática de datos personales.</p><button type="button" data-export>Exportar copia JSON</button> <label>Seleccionar copia JSON <input type="file" accept=".json,application/json" data-import></label><div data-preview hidden><p data-description></p><p>Se combinarán los registros sin borrar los actuales. En conflictos se conserva el valor de este navegador. La página se recargará al terminar.</p><button type="button" data-confirm>Combinar con mis datos</button> <button type="button" data-cancel>Cancelar</button></div><p data-message role="status"></p>';
const style=document.createElement('style');style.textContent='.pro-transfer{position:relative;clear:both;margin:24px 24px 100px auto;max-width:850px;padding:20px;border:1px solid #ccc;border-radius:14px;background:#fff;color:#333;font:14px/1.6 system-ui;box-sizing:border-box}.pro-transfer summary{cursor:pointer;font-weight:650}.pro-transfer h2{font-size:20px;margin:14px 0}.pro-transfer p{margin:12px 0}.pro-transfer button,.pro-transfer input{font:inherit;max-width:100%;margin:7px 0}.pro-transfer button{padding:10px 14px;background:#f3f3f3;color:#222;border:1px solid #aaa;border-radius:8px;cursor:pointer}.pro-transfer label{display:inline-block}.pro-transfer [data-preview]{padding:12px;background:#f4f4f4;border-radius:8px}@media(min-width:900px){.pro-transfer{width:calc(100% - 310px)}}@media(max-width:600px){.pro-transfer{margin:20px 12px 110px}.pro-transfer button{width:100%}}';document.head.append(style);document.body.append(panel);
const msg=t=>panel.querySelector('[data-message]').textContent=t;let pending=null;
panel.querySelector('[data-export]').onclick=()=>{try{const entries={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(allowed(k))entries[k]=JSON.parse(localStorage.getItem(k));}const data={app,version:1,exportedAt:Date.now(),entries};safe(entries);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=app+'-copia-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);msg('Copia descargada. Guárdala en un lugar de confianza.');}catch(e){msg('No se pudo exportar: '+e.message);}};
panel.querySelector('[data-import]').onchange=async e=>{pending=null;panel.querySelector('[data-preview]').hidden=true;try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('El archivo supera 5 MB.');const data=JSON.parse(await file.text());if(data.app!==app||data.version!==1||!data.entries||Array.isArray(data.entries)||typeof data.entries!=='object'||Object.keys(data.entries).some(k=>!allowed(k)))throw Error('La copia pertenece a otra aplicación o versión.');safe(data.entries);pending=data.entries;panel.querySelector('[data-description]').textContent=Object.keys(pending).length+' bloques de perfiles, preferencias e historial de '+app+'.';panel.querySelector('[data-preview]').hidden=false;msg('Revisa la copia antes de confirmar.');}catch(error){msg('No se ha importado: '+error.message);}finally{e.target.value='';}};
panel.querySelector('[data-cancel]').onclick=()=>{pending=null;panel.querySelector('[data-preview]').hidden=true;};
panel.querySelector('[data-confirm]').onclick=()=>{if(!pending)return;const rollback=new Map();try{const writes=Object.entries(pending).map(([k,v])=>{const raw=localStorage.getItem(k);rollback.set(k,raw);return [k,JSON.stringify(merge(raw?JSON.parse(raw):undefined,v))];});for(const [k,v]of writes)localStorage.setItem(k,v);msg('Copia importada. Recargando…');pending=null;location.reload();}catch(error){for(const [k,v]of rollback){try{v===null?localStorage.removeItem(k):localStorage.setItem(k,v);}catch{}}msg('No se pudo importar: '+error.message);}};
})();
